// Seats still free in a lab after some are booked (never below 0).
export function seatsLeft(capacity, booked) {
  return Math.max(0, capacity - booked);
}

import { seatsLeft } from '../src/seats.ts';

seatsLeft('40', 12); // expect TS2345
seatsLeft(40); // expect TS2554
const label: string = seatsLeft(40, 12); // expect TS2322
console.log(label);

import { seatsLeft } from '../src/seats.ts';

const free: number = seatsLeft(40, 12);
console.log(free, seatsLeft(30, 45));

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { seatsLeft } from '../src/seats.ts';

test('40 seats, 12 booked: 28 left', () => assert.equal(seatsLeft(40, 12), 28));
test('never below zero', () => assert.equal(seatsLeft(30, 45), 0));

