// Seats still free in a lab after some are booked (never below 0).
// Typing both parameters gives TS2345 (wrong type) and TS2554 (missing argument);
// the return type number gives TS2322 when someone stores it in a string.
export function seatsLeft(capacity: number, booked: number): number {
  return Math.max(0, capacity - booked);
