type Booking = { lab: string; minutes: number };

const bookings: Booking[] = [{ lab: 'BE-201', minutes: 120 }];
// TS18048: with noUncheckedIndexedAccess, bookings[0] is Booking | undefined.
const first = bookings[0];
console.log(first.lab);
// TS2551: "minute" is one letter away from "minutes", so tsc suggests it.
const b: Booking = { lab: 'BE-202', minutes: 60 };
